mapper.update:
UPDATE TB_STAY_ROOM
SET    NAME            = #{name},
       PRICE_PER_NIGHT = #{pricePerNight},
       CAPACITY        = #{capacity, jdbcType=NUMERIC},
       PET_LIMIT       = #{petLimit, jdbcType=NUMERIC}
WHERE  ROOM_ID = #{roomId}
  AND  STAY_ID = #{stayId}

UPDATE TB_STAY_ROOM
   SET STATUS_CD = #{statusCd}
 WHERE ROOM_ID = #{roomId}
   AND STAY_ID = #{stayId}

UPDATE TB_RESERVATION
   SET STATUS_CD = #{statusCd},
       REJECT_REASON = #{rejectReason, jdbcType=VARCHAR}
 WHERE RESV_ID   = #{resvId}
   AND TARGET_ID = TO_CHAR(#{stayId})
   AND RESV_TYPE = 'STAY'

